from pathlib import Path
import os
import pandas as pd,numpy as np,json,hashlib,gzip,datetime,platform,importlib.metadata
W=Path(os.environ.get('SCAID_BCELL_OUTPUT', 'work/bcell_state')).resolve();T=W/'tables';P=W/'provenance';S=Path(os.environ.get('SCAID_GSE174188_SOURCE', 'data/GSE174188')).resolve();OLD=Path(os.environ.get('SCAID_BASELINE_SCIENCE', 'data/baseline_science')).resolve()
T.mkdir(parents=True, exist_ok=True); P.mkdir(parents=True, exist_ok=True)
IFN=['ISG15','IFI6','IFI44L','MX1','OAS1','IFIT1','IFIT3','RSAD2','ISG20','XAF1','LY6E','IFI44'];MARKERS=['MS4A1','CD79A','CD74','TCL1A','IGHD','IGHM','FCER2','IL4R','CD27','TNFRSF13B','FCRL5','ITGAX','TBX21','JCHAIN','MZB1','XBP1']
sha=lambda p:hashlib.file_digest(open(p,'rb'),'sha256').hexdigest()
assert (OLD/'tables/GSE174188_frozen_one_batch_per_donor.tsv').is_file(), 'Required baseline selection table missing; see README input schema'
chosen=pd.read_csv(OLD/'tables/GSE174188_frozen_one_batch_per_donor.tsv',sep='\t');assert chosen.ind_cov.is_unique and len(chosen)==233
chosen['Age10']=(chosen.Age-40)/10;assert chosen[['Age10','Sex','pop_cov','cohort','condition']].notna().all().all();chosen.to_csv(T/'selected_individuals.tsv',sep='\t',index=False)
plan={'recorded_at_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'qualification':'Written before subgroup effect models and IFN extraction; the previously reported aggregate B-cell result was already known. This is an analysis plan, not external preregistration.','source':'GSE174188 locally archived remapped processed count matrix and original cg_cov/ct_cov metadata; not raw droplet or new cell-level QC.','batch_selection':'Reuse exactly the existing 233 individual/batch selections; largest total processed source cells among cohorts 2/3/4, lexical tie break. No selection by B abundance or IFN.','candidate_states':['B_naive','B_mem','B_atypical'],'annotation':'Use original ct_cov exactly among cg_cov=B. Other labels, missing and coarse/fine discordance remain a separately quantified residual. Plasma cells in cg_cov=PB are a different coarse compartment, not included. No IFN-derived state labels.','primary_composition':'Fraction of each state among all source cg_cov=B cells, with zero numerators retained, in individuals with at least 20 total B cells.','secondary_composition':'State fractions among all source PBMC cells in the full 233-person selection.','state_IFN':'Per-cell mean of the 12 log1p(count/library*10000) gene values, then mean over source-recorded state cells within each selected individual; at least 20 target-state cells per individual.','IFN_genes':IFN,'marker_review_panel':MARKERS,'model':'OLS: outcome ~ C(cohort) + Age10 + C(Sex) + C(pop_cov) + C(condition), condition HD as reference; HC3 covariance, independent observations are source individuals.','fit_eligibility':'At least 10 eligible individuals in each arm, full-rank design, residual degrees of freedom >=10 and finite positive HC3 disease standard error. No endpoint-dependent eligibility.','multiple_testing':{'state_composition_within_B':'BH across the three planned source-recorded states.','state_IFN':'BH across the same three planned states; any unestimable planned test is represented by P=1 for adjustment and reported unavailable.','state_composition_all_PBMC':'Separate BH family of three secondary state fractions.','matched_B_population':'Separate BH family of two endpoints: overall B fraction and aggregate B IFN in the same >=20-B-cell individuals.','common_state_population':'Separate BH across two eligible states × two endpoints (within-B fraction and state IFN), if the same common eligible population retains >=10 in each arm.','mixture_adjusted_IFN':'One exploratory aggregate B-IFN model, adding the three named state fractions with the residual state omitted; cannot establish cell-intrinsic activation.','marker_panel':'Descriptive review only; no marker-test P values or labels trained using IFN.'},'sensitivity':'Within-source sensitivity analyses overlap the original cohort and are not independent replication. Main published model estimates will not be overwritten.','limitations':'Observational source-recorded states; subtype proportions and IFN differences need not distinguish intrinsic expression from unmeasured states, treatment, disease activity or residual technical effects.'}
(P/'analysis_plan.json').write_text(json.dumps(plan,indent=2)+'\n');print('PLAN WRITTEN',flush=True)
m=pd.read_csv(S/'GSE174188_metadata.csv',usecols=['Unnamed: 0','ind_cov','batch_cov','Processing_Cohort','cg_cov','ct_cov','Age','Sex','pop_cov','SLE_status']).rename(columns={'Unnamed: 0':'cell_id'})
bar=pd.read_csv(S/'10x/barcodes.tsv.gz',sep='\t',header=None)[0].astype(str)
assert len(m)==len(bar) and np.array_equal(m.cell_id.to_numpy(),bar.to_numpy());assert m.cell_id.is_unique
m['unit_id']=m.ind_cov+'|'+m.batch_cov;uid=pd.Index(chosen.unit_id);selected=m.unit_id.isin(uid)
assert m.groupby('ind_cov').SLE_status.nunique().max()==1
allselected=m[selected].copy();counts=allselected.groupby('unit_id').size();assert np.array_equal(counts.reindex(chosen.unit_id).to_numpy(),chosen.n_cells.to_numpy())
b=m[selected&m.cg_cov.eq('B')].copy();b['source_matrix_column_1based']=b.index+1;b['B_index']=np.arange(len(b));b['state']=b.ct_cov.where(b.ct_cov.isin(plan['candidate_states']),'Source_B_other_or_unresolved')
assert b.ind_cov.nunique()<=233 and set(b.ind_cov)<=set(chosen.ind_cov)
b[['B_index','source_matrix_column_1based','cell_id','ind_cov','batch_cov','unit_id','cg_cov','ct_cov','state']].to_csv(T/'selected_B_cells_source_mapping.tsv.gz',sep='\t',index=False,compression='gzip')
cols=np.full(len(m)+1,-1,dtype='<i4');cols[b.source_matrix_column_1based.to_numpy()]=b.B_index.to_numpy();cols.tofile(P/'B_column_index.int32')
genes=pd.read_csv(S/'10x/features.tsv.gz',sep='\t',header=None)[0].astype(str);assert genes.is_unique
assert set(IFN)<=set(genes)
watch_requested=list(dict.fromkeys(IFN+MARKERS));watch=[g for g in watch_requested if g in set(genes)];missing_watch=[g for g in watch_requested if g not in set(genes)]
gmap=np.full(len(genes)+1,-1,dtype='<i4');idx={g:i for i,g in enumerate(genes,start=1)}
for i,g in enumerate(watch):gmap[idx[g]]=i
gmap.tofile(P/'watch_gene_index.int32');(P/'watch_genes.json').write_text(json.dumps(watch,indent=2)+'\n')
ct=pd.crosstab(b.unit_id,b.state).reindex(index=chosen.unit_id,columns=plan['candidate_states']+['Source_B_other_or_unresolved'],fill_value=0);ct['B_total']=ct.sum(axis=1)
per=chosen.set_index('unit_id').join(ct);per.to_csv(T/'B_state_counts_by_individual.tsv',sep='\t')
coverage=[]
for st in plan['candidate_states']+['Source_B_other_or_unresolved','B_total']:
 for arm in ['HD','SLE']:
  v=per.loc[per.condition.eq(arm),st];coverage.append({'state':st,'condition':arm,'source_cells':int(v.sum()),'n_individuals':len(v),'n_ge1':int(v.ge(1).sum()),'n_ge20':int(v.ge(20).sum()),'median_cells':float(v.median()),'min_cells':int(v.min()),'max_cells':int(v.max())})
pd.DataFrame(coverage).to_csv(T/'B_state_coverage_before_models.tsv',sep='\t',index=False)
raw=b.groupby(['cg_cov','ct_cov'],dropna=False).size().reset_index(name='cells');raw.to_csv(T/'source_B_coarse_fine_label_pairs.tsv',sep='\t',index=False)
meta={'source_metadata':{'path':str(S/'GSE174188_metadata.csv'),'sha256':sha(S/'GSE174188_metadata.csv')},'barcodes':{'path':str(S/'10x/barcodes.tsv.gz'),'sha256':sha(S/'10x/barcodes.tsv.gz')},'features':{'path':str(S/'10x/features.tsv.gz'),'sha256':sha(S/'10x/features.tsv.gz')},'existing_batch_selection':{'path':str(OLD/'tables/GSE174188_frozen_one_batch_per_donor.tsv'),'sha256':sha(OLD/'tables/GSE174188_frozen_one_batch_per_donor.tsv')},'selected_cell_mapping':{'path':str(T/'selected_B_cells_source_mapping.tsv.gz'),'sha256':sha(T/'selected_B_cells_source_mapping.tsv.gz')},'analysis_plan_sha256':sha(P/'analysis_plan.json'),'n_source_cells':len(m),'n_source_genes':len(genes),'n_selected_B_cells':len(b),'n_selected_individuals':len(chosen),'group_counts':chosen.condition.value_counts().to_dict(),'matrix_metadata_barcode_order_exact':True,'full_selected_batch_cell_counts_match_original':True,'source_state_counts':b.state.value_counts().to_dict(),'watch_genes':watch,'missing_requested_markers':missing_watch,'metadata_missing_by_covariate':chosen[['Age10','Sex','pop_cov','cohort','condition']].isna().sum().to_dict(),'source_matrix':str(S/'10x/matrix.mtx.gz'),'versions':{p:importlib.metadata.version(p) for p in ['numpy','pandas','statsmodels','openpyxl']},'python':platform.python_version()}
(P/'input_manifest.json').write_text(json.dumps(meta,indent=2)+'\n');print(json.dumps({k:meta[k] for k in ['n_selected_B_cells','source_state_counts','group_counts']}),flush=True)
